T=True
def N(sh, text, say=None): return [sh, None, text, None, None, None, say]
def C(sh, who, text, bubble=None, emo=None, think=False, say=None): return [sh, who, text, bubble, think, emo, say]
LIV = lambda at, props='': "{ type: 'living', at: { %s }, props: [%s] }" % (at, props)
TAGS = lambda *x: list(x)[:5]
