# ---------------------------------------------------------------- 010 future self
dict(id='tb3d-010-future-self', title="Don't hit snooze. Your old self is watching. 👴⏰", caption="Your 70-year-old self has opinions 👴\nTag who needs this 👇", tags=TAGS('futureself', 'motivation', 'funny', 'thoughtbubble', 'relatable'), comment="What would your old self yell at you for? 👇",
 voices={'you': 'guy', 'old': 'old'},
 lines=[N('hook', "Don't hit snooze. Your old self is watching."),
  N('bed', "Seven a.m. The alarm rings."),
  C('bed', 'you', "Five more minutes.", None, 'calm'),
  C('bed', 'old', "Five more minutes. That's how my knees went.", "THAT'S HOW MY KNEES WENT. 🦵", 'angry'),
  C('kit', 'you', "Coffee counts as water, right?", None, 'happy'),
  C('kit', 'old', "It does not. I have three kidney stones. I named them after you.", "3 KIDNEY STONES. NAMED AFTER YOU. 😤", 'sarcastic'),
  C('text', 'you', "Should I text my ex?", "TEXT MY EX? 📱", 'anxious', T),
  C('text', 'old', "Don't. You. Dare.", "DON'T. YOU. DARE. ☝️", 'angry'),
  N('text', "He texts his ex."),
  C('text', 'old', "Forty years of regret. Loading.", "40 YEARS OF REGRET… LOADING ▓▓░", 'sad'),
  N('run', "Then, one morning, he goes for a run."),
  C('run', 'old', "Wait. He's running. He's actually running!", "HE'S… RUNNING?! 😳", 'excited'),
  N('twist', "And the old man starts to fade."),
  C('twist', 'old', "No, no, wait! I'm changing! I'm sixty now. Nice.", "WAIT— I'M 60 NOW?! NICE. 😎", 'happy'),
  N('outro', "Tag the one who needs to see this. Don't hit snooze. Your old self is watching.")],
 spec="""{ hook: "DON'T HIT *SNOOZE*.\\nYOUR OLD SELF IS WATCHING.", tag: 'TAG WHO NEEDS THIS 👇', cast: { you: { body: 'm', look: 'e' }, old: { body: 'm', look: 'e', costume: 'old' } },
  sets: { bed: { type: 'bedroom', at: { you: [0.3, -0.6, 0.2], old: [-1.1, 0.5, 0.5] }, props: [['phone', 1.2, 0.6, -0.9, 0]] },
   kit: { type: 'kitchen', at: { you: [0.4, 0.3, -0.3], old: [-0.8, 0.6, 0.5] } },
   park: { type: 'park', at: { you: [0.5, 0.8, 0.3], old: [-0.8, 1.1, 0.4] } } },
  shots: { hook: { set: 'bed', cam: 'two', noBubble: true, card: '⏰ 7:00 AM', cardBg: '#d8504a' }, bed: { set: 'bed' }, kit: { set: 'kit' }, text: { set: 'bed', boom: ['SENT. 💀', 0.62] }, run: { set: 'park', pose: { you: 'run' } },
   twist: { set: 'park', pose: { you: 'run' }, move: (t, kk, a) => { a.old.traverse((m) => { if (m.material) { if (!m.material.transparent) { m.material.transparent = true; m.material.needsUpdate = true; } m.material.opacity = kk < 0.45 ? 1 - kk * 1.6 : 0.35 + (kk - 0.45) * 1.2; } }); } }, outro: { set: 'park', cam: 'wide', pose: { you: 'run' } } } }"""),
# ---------------------------------------------------------------- 011 time traveller
dict(id='tb3d-011-time-traveller', title="He's from 2090. And he's not allowed to warn you. ⏳", caption="Rule one of time travel: say nothing 🤐⏳\nTag the friend who'd crack in 5 minutes 👇", tags=TAGS('timetravel', 'future', 'funny', 'thoughtbubble', 'twist'), comment="What would you ask someone from 2090? 👇",
 voices={'trav': 'trav', 'raj': 'guy', 'mia': 'girl', 'waiter': 'waiter', 'ghost': 'ghost'},
 lines=[N('hook', "He's from 2090. And he's not allowed to warn you."),
  N('sit', "Rule one of time travel. Never tell anyone the future."),
  C('sit', 'raj', "Should I buy a house now, or wait?", None, 'calm'),
  C('sit', 'trav', "Buy. Buy now. No. Rule one.", "BUY. BUY NOW— NO. RULE ONE. 🤐", 'anxious', T),
  C('sit', 'mia', "Honestly, I think AI is just a phase.", None, 'content'),
  C('sit', 'trav', "Oh, you sweet summer child.", "OH… SWEET SUMMER CHILD. 🤖", 'sarcastic', T),
  C('water', 'waiter', "That's four hundred rupees for the water.", None, 'calm'),
  C('water', 'trav', "You pay for water? You pay for water?", "YOU PAY FOR WATER?! 💧", 'scared'),
  C('slip', 'raj', "Anyway, I'm putting all my savings into...", None, 'excited'),
  C('slip', 'trav', "Don't! I mean. Don't forget your umbrella.", "DON'T!— …FORGET YOUR UMBRELLA. ☂️", 'anxious'),
  N('twist', "Then he vanishes. Mid sentence."),
  C('twist', 'mia', "Did he just disappear?", "DID HE JUST… DISAPPEAR? 😳", 'scared'),
  C('twist', 'ghost', "Every Tuesday. Same guy.", "EVERY TUESDAY. SAME GUY. 👻", 'sarcastic'),
  N('outro', "Tag the friend who'd ruin time travel in five minutes. He's from 2090. And he's not allowed to warn you.")],
 spec="""{ hook: "HE'S FROM *2090*.\\nHE'S NOT ALLOWED TO WARN YOU.", tag: "TAG WHO'D CRACK IN 5 MINUTES 👇", cast: { trav: { body: 'm', look: 'a', costume: 'traveller' }, raj: { body: 'm', look: 'd' }, mia: { body: 'f', look: 'c' }, waiter: { body: 'm', look: 'f' }, ghost: { ghost: true } },
  sets: { cafe: { type: 'cafe', at: { raj: [-3.0, 1.6, 0.9], mia: [-1.8, 1.6, -0.9], trav: [3.0, 1.6, -0.9], waiter: [2.3, 0.7, 0.2], ghost: [-0.4, 1.0, -1.6] }, props: [['cups', -2.4, 0.81, 1.6, 0], ['cups', 2.4, 0.81, 1.6, 0]] } },
  shots: { hook: { set: 'cafe', cam: 'close:trav', noBubble: true, hide: ['waiter'] }, sit: { set: 'cafe', hide: ['waiter'] }, water: { set: 'cafe' }, slip: { set: 'cafe', hide: ['waiter'] },
   twist: { set: 'cafe', hide: ['waiter', 'trav'], boom: ['POOF ✨', 0.05] }, outro: { set: 'cafe', cam: 'wide', hide: ['waiter', 'trav'] } } }"""),
