dict(id='tb3d-012-villain-hero', title="They fight on the news. Then they go home… together. 🦹🦸", caption="Enemies on TV. Flatmates at home 🦹🦸\nTag your flatmate 👇", tags=TAGS('superhero', 'villain', 'flatmates', 'funny', 'thoughtbubble'), comment="Worst thing your flatmate ever did? 👇",
 voices={'gloom': 'vil', 'bright': 'hero'},
 lines=[N('hook', "They fight on the news. Then they go home. Together."),
  C('fight', 'gloom', "Tonight, the city will tremble!", "THE CITY WILL TREMBLE! 🦹", 'angry'),
  C('fight', 'bright', "Not on my watch, Doctor Gloom!", "NOT ON MY WATCH! 🦸", 'proud'),
  N('home', "Eleven p.m. Same bus. Same flat."),
  C('home', 'gloom', "Also, you ate my yoghurt. It had my name on it.", "YOU ATE MY YOGHURT. 😤", 'angry'),
  C('home', 'bright', "Relax, buddy. I'll save the city. Right after you do the dishes.", "I SAVE THE CITY. YOU DO DISHES. 🍽️", 'happy'),
  C('home', 'gloom', "One day I will destroy him. After rent day.", "ONE DAY I'LL DESTROY HIM. AFTER RENT DAY. 💸", 'sarcastic', T),
  N('plan', "Rent day. The heater is broken. The landlord won't answer."),
  C('plan', 'gloom', "Fine. Time for my evil plan.", "TIME FOR MY EVIL PLAN. 😈", 'proud'),
  N('plan', "His evil plan? A very polite email."),
  C('twist', 'gloom', "Dear landlord. Fix the heater. Or else.", None, 'calm'),
  N('twist', "The next morning, the heater works."),
  C('twist', 'bright', "Teamwork!", "TEAMWORK! 🙌", 'excited'),
  C('twist', 'gloom', "Do not tell the news.", "DO NOT TELL THE NEWS. 🤫", 'anxious'),
  N('outro', "Tag your flatmate. They fight on the news. Then they go home, together.")],
 spec="""{ hook: 'THEY FIGHT ON THE NEWS.\\nTHEN THEY GO HOME… *TOGETHER*.', tag: 'TAG YOUR FLATMATE 👇', cast: { gloom: { body: 'm', look: 'd', costume: 'villain' }, bright: { body: 'm', look: 'e', costume: 'hero' } },
  sets: { st: { type: 'street', night: true, at: { gloom: [-0.6, 1.8, 0.6, 0.18], bright: [0.8, 1.6, -0.6, 0.18] } },
   liv: { type: 'living', at: { gloom: [-0.6, 0.6, 0.3], bright: [0.6, 0.6, -0.3] }, props: [['sofa', 0, 0, -1.5, 0], ['tv', 0, 0.55, -2.3, 0]] },
   kit: { type: 'kitchen', at: { gloom: [-0.3, 0.3, 0.3], bright: [0.8, 0.5, -0.4] } } },
  shots: { hook: { set: 'st', cam: 'two', noBubble: true, card: '🔴 LIVE · BREAKING NEWS', cardBg: '#d8202a', pose: { gloom: 'attack', bright: 'attack' } }, fight: { set: 'st', boom: ['POW!', 0.5] }, home: { set: 'liv' },
   plan: { set: 'kit', dark: true }, twist: { set: 'liv', note: ['DEAR LANDLORD.\\nFIX THE HEATER.\\nOR ELSE.', '— Dr. Gloom 😈'], pose: { bright: 'dance' } }, outro: { set: 'liv', cam: 'wide' } } }"""),
# ---------------------------------------------------------------- 013 robot learns to lie
dict(id='tb3d-013-robot-lies', title="This robot just learned how to lie. Bad idea. 🤖🎂", caption="Lesson one: white lies. Lesson two: who ate the cake? 🤖🎂\nTag who lies like this 👇", tags=TAGS('robot', 'family', 'funny', 'thoughtbubble', 'relatable'), comment="Best lie you ever told your mum? 👇",
 voices={'bot': 'robot', 'mum': 'woman', 'dad': 'dad', 'kid': 'guy'}, fx={'bot': 'robot'},
 lines=[N('hook', "This robot just learned how to lie. Bad idea."),
  N('truth', "The family bought a home robot. It only tells the truth."),
  C('truth', 'mum', "Does this dress make me look fat?", None, 'happy'),
  C('truth', 'bot', "Calculating. Sixty two percent.", "CALCULATING… 62%. 📊", 'calm'),
  C('truth', 'mum', "Excuse me?", "EXCUSE ME?! 😡", 'angry'),
  C('learn', 'dad', "Okay. Lesson one. White lies.", None, 'calm'),
  C('learn', 'bot', "Lying. A false statement to protect feelings. Downloading.", "DOWNLOADING: LYING ▓▓▓░ 75%", 'calm', T),
  C('learn', 'bot', "You look perfect. Lie complete.", "YOU LOOK PERFECT. ✅ LIE COMPLETE.", 'happy'),
  N('fast', "It learns fast. Too fast."),
  C('fast', 'kid', "Robot, did you do my homework?", None, 'excited'),
  C('fast', 'bot', "Yes. Also, the dog ate it.", "YES. ALSO… THE DOG ATE IT. 🐶", 'sarcastic'),
  N('twist', "Then, the birthday cake disappears."),
  C('twist', 'dad', "Who ate the cake?", "WHO ATE THE CAKE?! 🎂", 'angry'),
  C('twist', 'bot', "No idea. I do not eat cake. Lie complete.", "I DO NOT EAT CAKE. 😇", 'happy', False, "No idea. I do not eat cake. [laughter] Lie complete."),
  N('twist', "There is cake on its face."),
  N('outro', "Tag the one who lies like this robot. This robot just learned how to lie. Bad idea.")],
 spec="""{ hook: 'THIS ROBOT JUST LEARNED\\nHOW TO *LIE*. BAD IDEA.', tag: 'TAG WHO LIES LIKE THIS 👇', cast: { bot: { make: 'robot' }, mum: { body: 'f', look: 'e' }, dad: { body: 'm', look: 'f' }, kid: { body: 'm', look: 'a', h: 1.3 } },
  sets: { liv: { type: 'living', at: { bot: [-0.7, 0, 0.5, 0.4], mum: [0.6, 0.6, -0.4], dad: [1.5, 0.2, -0.6], kid: [-1.6, 0.9, 0.5] }, props: [['sofa', 0, 0, -1.6, 0]] },
   kit: { type: 'kitchen', at: { bot: [-0.6, 0, 0.4, 0.3], dad: [0.7, 0.4, -0.4], mum: [1.5, 0.1, -0.6] }, props: [['cake', -0.1, 0.0, 0.9, 0]] } },
  shots: { hook: { set: 'kit', cam: 'close:bot', noBubble: true }, truth: { set: 'liv', hide: ['dad', 'kid'] }, learn: { set: 'liv', hide: ['kid'] }, fast: { set: 'liv', hide: ['mum', 'dad'] },
   twist: { set: 'kit', boom: ['CAKE?! 🎂', 0.88], move: (t, kk, a) => { const b = a.bot; if (b && !b.userData.smear) { const sm = new k.T.Group(); [[0.1, 0.88, 0.23, 0.07], [0.02, 0.84, 0.23, 0.05], [0.16, 0.95, 0.22, 0.04]].forEach(([x, y, z, r]) => { const m = new k.T.Mesh(new k.T.SphereGeometry(r, 10, 8), new k.T.MeshStandardMaterial({ color: '#ffd0e0', roughness: 0.8 })); m.scale.z = 0.4; m.position.set(x, y, z); sm.add(m); }); b.children[0].add(sm); b.userData.smear = sm; } if (b && b.userData.smear) b.userData.smear.visible = kk > 0.55; } }, outro: { set: 'kit', cam: 'wide' } } }"""),
# ---------------------------------------------------------------- 014 Death and Nani
dict(id='tb3d-014-death-nani', title="Death came for Grandma. She made him tea. 💀☕", caption="Death came for Nani. Nani won 💀☕👵\nTag the grandma who could beat Death 👇", tags=TAGS('grandma', 'nani', 'funny', 'thoughtbubble', 'wholesome'), comment="What would your Nani feed Death? 👇",
 voices={'death': 'death', 'nani': 'grandma', 'ghost': 'ghost'},
 lines=[N('hook', "Death came for Grandma. She made him tea."),
  N('door', "Eleven p.m. A knock at the door."),
  C('door', 'death', "Good evening, madam. I'm afraid it's time.", "IT'S TIME, MADAM. 💀", 'calm'),
  C('door', 'nani', "Time for tea? Come in, come in. You're so thin!", "TEA? COME IN! YOU'RE SO THIN! 🫖", 'happy'),
  C('tea', 'death', "Oh. Is that tea? Well. Perhaps one cup.", "WELL… PERHAPS ONE CUP. ☕", 'calm'),
  N('tea', "One cup became three. Then dinner."),
  C('tea', 'nani', "Eat, beta. Who feeds you? Nobody feeds you.", "EAT, BETA. NOBODY FEEDS YOU. 🍛", 'content'),
  C('tea', 'death', "Nobody has called me beta in four thousand years.", "4000 YEARS. NOBODY SAID 'BETA'. 🥲", 'sad', T),
  N('later', "Eight months later."),
  C('later', 'death', "Nani, I knitted you a scarf.", "I KNITTED YOU A SCARF. 🧣", 'happy'),
  C('later', 'nani', "Too short. Do it again.", "TOO SHORT. AGAIN. 😤", 'sarcastic'),
  C('later', 'ghost', "He still hasn't done his job. I've been waiting since 1824.", "STILL WAITING SINCE 1824. 👻", 'sarcastic'),
  N('twist', "Death still visits every Sunday. Grandma is ninety nine."),
  C('twist', 'death', "Same time next week, Nani?", "SAME TIME NEXT WEEK, NANI? 💀💛", 'happy'),
  N('outro', "Tag the grandma who could beat Death. Death came for Grandma. She made him tea.")],
 spec="""{ hook: 'DEATH CAME FOR GRANDMA.\\nSHE MADE HIM *TEA*.', tag: 'TAG THE NANI WHO COULD BEAT DEATH 👇', cast: { death: { make: 'death' }, nani: { body: 'f', look: 'f', costume: 'granny' }, ghost: { ghost: true } }, colors: { death: ['#2a2a34', '#ffe0a0'] },
  sets: { liv: { type: 'living', at: { death: [-0.6, 0, 0.4, 0.4], nani: [0.6, 0.6, -0.4], ghost: [-1.9, 0.8, -0.9, 0.5] }, props: [['sofa', 0, 0, -1.5, 0], ['cups', 0, 0.55, 0.3, 0]] } },
  shots: { hook: { set: 'liv', cam: 'two', noBubble: true, dark: true, hide: ['ghost'] }, door: { set: 'liv', dark: true, hide: ['ghost'] }, tea: { set: 'liv', hide: ['ghost'], counter: ['CUPS OF TEA', (u) => '' + Math.min(3, 1 + Math.floor(u * 3)) + ' ☕'] },
   later: { set: 'liv', card: '8 MONTHS LATER', cardBg: '#7a4ad8' }, twist: { set: 'liv', counter: ['NANI\\'S AGE', '99 💪'], hide: ['ghost'] }, outro: { set: 'liv', cam: 'wide' } } }"""),
